import { Canvas, useFrame } from '@react-three/fiber'
import { Line, OrbitControls } from '@react-three/drei'
import { useEffect, useLayoutEffect, useMemo, useRef, useState, type ComponentRef } from 'react'
import * as THREE from 'three'
import { useMotionProfile, type MotionProfile } from '../hooks/useMotionProfile'
import { sampleTerrainHeight } from './particleTerrainMath'

export type EcoDomain = 'air' | 'water' | 'forest'

export interface TriadEcoCoreProps {
  domain: EcoDomain
  wakeStage: number
  resetViewSignal: number
}

const DOMAIN_INDEX: Record<EcoDomain, number> = { air: 0, water: 1, forest: 2 }
const DOMAIN_COLOR: Record<EcoDomain, string> = { air: '#CBFF38', water: '#69D6C5', forest: '#45FF78' }

const hash = (x: number, y: number) => {
  const value = Math.sin(x * 12.9898 + y * 78.233) * 43758.5453
  return value - Math.floor(value)
}

function createCoreGeometry(profile: MotionProfile) {
  const [columns, rows] = profile === 'full' ? [220, 164] : profile === 'lite' ? [148, 104] : [98, 70]
  const positions = new Float32Array(columns * rows * 3)
  const elevations = new Float32Array(columns * rows)
  const randoms = new Float32Array(columns * rows)
  let offset = 0
  for (let row = 0; row < rows; row += 1) {
    for (let column = 0; column < columns; column += 1) {
      const x = column / (columns - 1) * 10.7 - 5.35 + (hash(column, row) - .5) * .026
      const z = row / (rows - 1) * 7.2 - 3.6 + (hash(row + 47, column + 71) - .5) * .026
      const y = sampleTerrainHeight(x * 1.08, z * 1.08) * 1.13
      positions[offset * 3] = x
      positions[offset * 3 + 1] = y
      positions[offset * 3 + 2] = z
      elevations[offset] = THREE.MathUtils.clamp((y + 1.35) / 4.6, 0, 1)
      randoms[offset] = hash(column + 11, row + 91)
      offset += 1
    }
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  geometry.setAttribute('aElevation', new THREE.BufferAttribute(elevations, 1))
  geometry.setAttribute('aRandom', new THREE.BufferAttribute(randoms, 1))
  geometry.computeBoundingSphere()
  return geometry
}

const coreVertexShader = `
  attribute float aElevation;
  attribute float aRandom;
  uniform float uTime;
  uniform float uPointScale;
  uniform float uActivation;
  varying float vElevation;
  varying float vRandom;
  void main() {
    vElevation = aElevation;
    vRandom = aRandom;
    vec3 displaced = position;
    displaced.y += sin(uTime * .48 + aRandom * 20.0) * .012 * uActivation;
    vec4 mvPosition = modelViewMatrix * vec4(displaced, 1.0);
    gl_Position = projectionMatrix * mvPosition;
    gl_PointSize = clamp(uPointScale * (.63 + aElevation * .86 + aRandom * .16) / max(1.0, -mvPosition.z), 1.0, 4.25);
  }
`

const coreFragmentShader = `
  uniform float uDomain;
  uniform float uActivation;
  uniform float uOpacity;
  varying float vElevation;
  varying float vRandom;
  void main() {
    vec2 point = gl_PointCoord - vec2(.5);
    float radius = length(point);
    if (radius > .5) discard;
    float core = smoothstep(.5, .05, radius);

    vec3 deep = vec3(.00, .18, .15);
    vec3 airLow = vec3(.05, .57, .42);
    vec3 airHigh = vec3(.80, 1.0, .22);
    vec3 waterLow = vec3(.00, .24, .34);
    vec3 waterHigh = vec3(.41, .84, .77);
    vec3 forestLow = vec3(.04, .30, .17);
    vec3 forestHigh = vec3(.27, 1.0, .47);

    vec3 airColor = mix(airLow, airHigh, smoothstep(.05, .82, vElevation));
    vec3 waterColor = mix(waterLow, waterHigh, smoothstep(.02, .88, vElevation));
    vec3 forestColor = mix(forestLow, forestHigh, smoothstep(.03, .72, vElevation));
    float airWeight = 1.0 - smoothstep(.0, 1.0, uDomain);
    float forestWeight = smoothstep(1.0, 2.0, uDomain);
    float waterWeight = max(0.0, 1.0 - airWeight - forestWeight);
    vec3 color = airColor * airWeight + waterColor * waterWeight + forestColor * forestWeight;
    color = mix(deep, color, .38 + uActivation * .62);
    float shimmer = .72 + vRandom * .34 + vElevation * .22;
    gl_FragColor = vec4(color * shimmer, core * uOpacity * (.40 + uActivation * .60));
  }
`

function TerrainParticles({ domain, wakeStage, profile }: { domain: EcoDomain; wakeStage: number; profile: MotionProfile }) {
  const geometry = useMemo(() => createCoreGeometry(profile), [profile])
  const targetDomain = DOMAIN_INDEX[domain]
  const targetActivation = wakeStage >= 5 ? 1 : wakeStage >= 1 ? .32 + wakeStage * .12 : .22
  const material = useMemo(() => new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uDomain: { value: 0 },
      uActivation: { value: .22 },
      uOpacity: { value: .98 },
      uPointScale: { value: profile === 'full' ? 30 : profile === 'lite' ? 25 : 21 },
    },
    vertexShader: coreVertexShader,
    fragmentShader: coreFragmentShader,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  }), [profile])

  useEffect(() => () => { geometry.dispose(); material.dispose() }, [geometry, material])
  useFrame((state, delta) => {
    if (profile !== 'reduced') material.uniforms.uTime.value = state.clock.elapsedTime
    material.uniforms.uDomain.value = THREE.MathUtils.damp(material.uniforms.uDomain.value, targetDomain, 4.2, delta)
    material.uniforms.uActivation.value = THREE.MathUtils.damp(material.uniforms.uActivation.value, targetActivation, 3.6, delta)
  })
  return <points geometry={geometry} material={material} frustumCulled={false} />
}

function createAirGeometry(profile: MotionProfile) {
  const count = profile === 'full' ? 1800 : profile === 'lite' ? 780 : 360
  const positions = new Float32Array(count * 3)
  const randoms = new Float32Array(count)
  for (let index = 0; index < count; index += 1) {
    const x = (hash(index, 12) - .5) * 11.2
    const z = (hash(index, 44) - .5) * 7.4
    positions[index * 3] = x
    positions[index * 3 + 1] = sampleTerrainHeight(x * 1.08, z * 1.08) * 1.13 + .75 + hash(index, 86) * 2.15
    positions[index * 3 + 2] = z
    randoms[index] = hash(index, 133)
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3))
  geometry.setAttribute('aRandom', new THREE.BufferAttribute(randoms, 1))
  return geometry
}

const airVertexShader = `
  attribute float aRandom;
  uniform float uTime;
  uniform float uStrength;
  varying float vAlpha;
  void main() {
    vec3 p = position;
    p.x += sin(uTime * (.16 + aRandom * .18) + p.z) * (.18 + aRandom * .32) * uStrength;
    p.z += cos(uTime * .18 + p.x * .44) * .12 * uStrength;
    p.y += sin(uTime * .35 + aRandom * 17.0) * .07 * uStrength;
    vec4 mvPosition = modelViewMatrix * vec4(p, 1.0);
    gl_Position = projectionMatrix * mvPosition;
    gl_PointSize = clamp((10.0 + aRandom * 13.0) / max(1.0, -mvPosition.z), .8, 2.3);
    vAlpha = .28 + aRandom * .72;
  }
`

const airFragmentShader = `
  uniform float uOpacity;
  varying float vAlpha;
  void main() {
    float d = length(gl_PointCoord - vec2(.5));
    if (d > .5) discard;
    gl_FragColor = vec4(.80, 1.0, .22, smoothstep(.5, .04, d) * vAlpha * uOpacity);
  }
`

function AirField({ domain, wakeStage, profile }: { domain: EcoDomain; wakeStage: number; profile: MotionProfile }) {
  const geometry = useMemo(() => createAirGeometry(profile), [profile])
  const material = useMemo(() => new THREE.ShaderMaterial({
    uniforms: { uTime: { value: 0 }, uOpacity: { value: 0 }, uStrength: { value: 0 } },
    vertexShader: airVertexShader,
    fragmentShader: airFragmentShader,
    transparent: true,
    depthWrite: false,
    blending: THREE.AdditiveBlending,
  }), [])
  const targetOpacity = wakeStage >= 2 ? domain === 'air' ? .9 : .2 : 0
  useEffect(() => () => { geometry.dispose(); material.dispose() }, [geometry, material])
  useFrame((state, delta) => {
    if (profile !== 'reduced') material.uniforms.uTime.value = state.clock.elapsedTime
    material.uniforms.uOpacity.value = THREE.MathUtils.damp(material.uniforms.uOpacity.value, targetOpacity, 4, delta)
    material.uniforms.uStrength.value = THREE.MathUtils.damp(material.uniforms.uStrength.value, domain === 'air' ? 1 : .35, 4, delta)
  })
  return <points geometry={geometry} material={material} />
}

function WaterFlow({ domain, wakeStage, profile }: { domain: EcoDomain; wakeStage: number; profile: MotionProfile }) {
  const paths = useMemo(() => [-1.45, .05, 1.38].map((baseZ, pathIndex) => Array.from({ length: 70 }, (_, index) => {
    const x = index / 69 * 10.4 - 5.2
    const z = baseZ + Math.sin(x * .65 + pathIndex * 1.7) * (.38 + pathIndex * .08)
    return new THREE.Vector3(x, sampleTerrainHeight(x * 1.08, z * 1.08) * 1.13 + .08, z)
  })), [])
  const curves = useMemo(() => paths.map((points) => new THREE.CatmullRomCurve3(points)), [paths])
  const beads = useRef<Array<THREE.Mesh | null>>([])
  const group = useRef<THREE.Group>(null)
  const targetReveal = wakeStage >= 3 ? 1 : .001
  const targetOpacity = wakeStage >= 3 ? domain === 'water' ? 1 : .18 : 0
  useFrame((state, delta) => {
    if (group.current) group.current.scale.y = THREE.MathUtils.damp(group.current.scale.y, targetReveal, 4.5, delta)
    beads.current.forEach((bead, index) => {
      if (!bead) return
      const curve = curves[index % curves.length]
      const t = profile === 'reduced' ? index / beads.current.length : (state.clock.elapsedTime * .075 + index * .19) % 1
      bead.position.copy(curve.getPoint(t))
      const material = bead.material as THREE.MeshBasicMaterial
      material.opacity = targetOpacity
    })
  })
  return (
    <group ref={group} scale={[1, .001, 1]}>
      {paths.map((points, index) => <Line key={index} points={points} color={index === 1 ? '#B8FFF4' : '#69D6C5'} transparent opacity={wakeStage >= 3 ? domain === 'water' ? .96 : .18 : 0} lineWidth={domain === 'water' ? 1.7 : .7} />)}
      {Array.from({ length: profile === 'full' ? 15 : 9 }, (_, index) => (
        <mesh key={index} ref={(node) => { beads.current[index] = node }}>
          <sphereGeometry args={[index % 3 === 0 ? .055 : .035, 8, 8]} />
          <meshBasicMaterial color={index % 3 === 0 ? '#FAF7EF' : '#69D6C5'} transparent opacity={0} blending={THREE.AdditiveBlending} />
        </mesh>
      ))}
    </group>
  )
}

function createForestGeometry(profile: MotionProfile) {
  const count = profile === 'full' ? 2100 : profile === 'lite' ? 820 : 380
  const positions: number[] = []
  const colors: number[] = []
  const jade = new THREE.Color('#45FF78')
  const lime = new THREE.Color('#CBFF38')
  let candidate = 0
  while (positions.length / 3 < count && candidate < count * 8) {
    const x = (hash(candidate, 23) - .5) * 10.3
    const z = (hash(candidate, 63) - .5) * 6.8
    const y = sampleTerrainHeight(x * 1.08, z * 1.08) * 1.13
    const cluster = Math.sin(x * .82) + Math.cos(z * 1.13)
    if (y > -.18 && cluster > -.15) {
      const lift = .05 + hash(candidate, 97) * .28
      positions.push(x, y + lift, z)
      const color = jade.clone().lerp(lime, hash(candidate, 141) * .44)
      colors.push(color.r, color.g, color.b)
    }
    candidate += 1
  }
  const geometry = new THREE.BufferGeometry()
  geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3))
  geometry.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3))
  return geometry
}

function ForestField({ domain, wakeStage, profile }: { domain: EcoDomain; wakeStage: number; profile: MotionProfile }) {
  const geometry = useMemo(() => createForestGeometry(profile), [profile])
  const material = useMemo(() => new THREE.PointsMaterial({ size: profile === 'full' ? .065 : .075, vertexColors: true, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true }), [profile])
  const group = useRef<THREE.Points>(null)
  const targetOpacity = wakeStage >= 4 ? domain === 'forest' ? .96 : .14 : 0
  useEffect(() => () => { geometry.dispose(); material.dispose() }, [geometry, material])
  useFrame((state, delta) => {
    material.opacity = THREE.MathUtils.damp(material.opacity, targetOpacity, 4, delta)
    if (group.current && profile !== 'reduced') group.current.scale.y = 1 + Math.sin(state.clock.elapsedTime * .45) * (domain === 'forest' ? .025 : .006)
  })
  return <points ref={group} geometry={geometry} material={material} />
}

function Scanner({ domain, wakeStage, profile }: { domain: EcoDomain; wakeStage: number; profile: MotionProfile }) {
  const group = useRef<THREE.Group>(null)
  const ticks = useRef<THREE.InstancedMesh>(null)
  const dot = useRef<THREE.Mesh>(null)
  const accent = DOMAIN_COLOR[domain]
  useLayoutEffect(() => {
    if (!ticks.current) return
    const object = new THREE.Object3D()
    for (let index = 0; index < 96; index += 1) {
      const angle = index / 96 * Math.PI * 2
      object.position.set(Math.cos(angle) * 5.9, -.86, Math.sin(angle) * 5.9)
      object.rotation.set(0, -angle, 0)
      object.scale.set(index % 8 === 0 ? 1.8 : .62, 1, 1)
      object.updateMatrix()
      ticks.current.setMatrixAt(index, object.matrix)
    }
    ticks.current.instanceMatrix.needsUpdate = true
  }, [])
  useFrame((state, delta) => {
    if (group.current && profile !== 'reduced') group.current.rotation.y += delta * (wakeStage > 0 && wakeStage < 5 ? .42 : .035)
    if (dot.current) {
      const angle = profile === 'reduced' ? .9 : state.clock.elapsedTime * (wakeStage > 0 && wakeStage < 5 ? 1.5 : .26)
      dot.current.position.set(Math.cos(angle) * 5.9, -.81, Math.sin(angle) * 5.9)
    }
  })
  return (
    <group>
      <group ref={group}>
        <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, -.86, 0]}><torusGeometry args={[5.9, .018, 6, 192]} /><meshBasicMaterial color={accent} transparent opacity={wakeStage ? .72 : .18} blending={THREE.AdditiveBlending} /></mesh>
        <mesh rotation={[Math.PI / 2, 0, 0]} position={[0, -.58, 0]}><torusGeometry args={[5.18, .009, 5, 160]} /><meshBasicMaterial color="#FAF7EF" transparent opacity={wakeStage >= 5 ? .18 : .06} /></mesh>
        <instancedMesh ref={ticks} args={[undefined, undefined, 96]}><boxGeometry args={[.11, .016, .012]} /><meshBasicMaterial color={accent} transparent opacity={wakeStage ? .66 : .12} /></instancedMesh>
      </group>
      <mesh ref={dot}><sphereGeometry args={[.055, 10, 10]} /><meshBasicMaterial color="#FAF7EF" transparent opacity={wakeStage ? 1 : .25} blending={THREE.AdditiveBlending} /></mesh>
    </group>
  )
}

function CoreScene({ props, profile }: { props: TriadEcoCoreProps; profile: MotionProfile }) {
  const controls = useRef<ComponentRef<typeof OrbitControls>>(null)
  const core = useRef<THREE.Group>(null)
  useEffect(() => { controls.current?.reset() }, [props.resetViewSignal])
  useFrame((state, delta) => {
    if (!core.current) return
    const pointerX = profile === 'full' ? state.pointer.x * .055 : 0
    const pointerY = profile === 'full' ? state.pointer.y * .035 : 0
    core.current.rotation.z = THREE.MathUtils.damp(core.current.rotation.z, pointerX, 2.2, delta)
    core.current.rotation.x = THREE.MathUtils.damp(core.current.rotation.x, pointerY, 2.2, delta)
    core.current.position.y = profile === 'reduced' ? 0 : Math.sin(state.clock.elapsedTime * .28) * .035
  })
  return (
    <>
      <color attach="background" args={['#030705']} />
      <fog attach="fog" args={['#030705', 10, 21]} />
      <ambientLight intensity={.22} />
      <pointLight position={[0, 6, 2]} intensity={2.6} color={DOMAIN_COLOR[props.domain]} distance={16} />
      <pointLight position={[-5, 2, -2]} intensity={1.2} color="#69D6C5" distance={12} />
      <group ref={core}>
        <TerrainParticles domain={props.domain} wakeStage={props.wakeStage} profile={profile} />
        <AirField domain={props.domain} wakeStage={props.wakeStage} profile={profile} />
        <WaterFlow domain={props.domain} wakeStage={props.wakeStage} profile={profile} />
        <ForestField domain={props.domain} wakeStage={props.wakeStage} profile={profile} />
      </group>
      <Scanner domain={props.domain} wakeStage={props.wakeStage} profile={profile} />
      <gridHelper args={[18, 36, '#173a2d', '#09150f']} position={[0, -1.72, 0]} />
      <OrbitControls
        ref={controls}
        makeDefault
        enablePan={false}
        enableDamping
        dampingFactor={.065}
        autoRotate={profile === 'full' && props.wakeStage >= 5}
        autoRotateSpeed={.22}
        minDistance={7.4}
        maxDistance={13.5}
        minPolarAngle={.53}
        maxPolarAngle={1.3}
        target={[0, .28, 0]}
      />
    </>
  )
}

const supportsWebGL = () => {
  try {
    const canvas = document.createElement('canvas')
    return Boolean(canvas.getContext('webgl2') || canvas.getContext('webgl'))
  } catch {
    return false
  }
}

export function TriadEcoCore(props: TriadEcoCoreProps) {
  const profile = useMotionProfile()
  const [webgl, setWebgl] = useState<boolean | null>(null)
  const pointCount = profile === 'full' ? 36080 : profile === 'lite' ? 15392 : 6860
  useEffect(() => setWebgl(supportsWebGL()), [])
  return (
    <div className={`triad-eco-core triad-domain-${props.domain} motion-${profile}`} role="img" aria-label={`${props.domain === 'air' ? '空气' : props.domain === 'water' ? '水环境' : '森林'}主题的程序化生态概念装置。场景不是贵州真实地形或遥感影像。`}>
      {webgl ? (
        <Canvas
          aria-hidden="true"
          dpr={profile === 'full' ? [1, 1.45] : 1}
          camera={{ position: [8.4, 5.5, 8.8], fov: 39, near: .1, far: 36 }}
          gl={{ antialias: profile === 'full', alpha: false, powerPreference: 'high-performance' }}
        >
          <CoreScene props={props} profile={profile} />
        </Canvas>
      ) : (
        <div className="triad-core-fallback" aria-hidden="true"><i /><i /><i /><span /></div>
      )}
      <div className="triad-core-grid" aria-hidden="true" />
      <div className="triad-core-vignette" aria-hidden="true" />
      <p className="triad-core-note">{pointCount.toLocaleString()} TERRAIN POINTS · PROCEDURAL ECO ART / 概念地形·非真实GIS</p>
    </div>
  )
}
